using System;using System.Collections.Generic;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class AtmosphereTravelTitleInstaller {
 [MenuItem("Codebound/Preparar edicion de titulo y viajes agrupados")]
 public static string Install(){
 Directory.CreateDirectory("Assets/Resources/UI/Title");var layout=AssetDatabase.LoadAssetAtPath<CodeboundTitleSettings>("Assets/Resources/UI/Title/Settings.asset");if(layout==null){layout=ScriptableObject.CreateInstance<CodeboundTitleSettings>();AssetDatabase.CreateAsset(layout,"Assets/Resources/UI/Title/Settings.asset");}
 var titleScene=EditorSceneManager.OpenScene("Assets/Scenes/CodeboundTitle.unity",OpenSceneMode.Additive);foreach(var root in titleScene.GetRootGameObjects()){var title=root.GetComponent<CodeboundTitleScreen>();if(title==null)continue;if(layout.background==null)layout.background=title.background;if(layout.logo==null)layout.logo=title.logo;if(layout.music==null)layout.music=title.music;title.presentation=layout;EditorUtility.SetDirty(title);}EditorSceneManager.SaveScene(titleScene);EditorSceneManager.CloseScene(titleScene,true);EditorUtility.SetDirty(layout);
 var city=DigitalKingdomSettings.Current;var travel=Array.Find(city.locations,l=>l!=null&&l.service==DigitalKingdomService.Travel);var guide=Array.Find(city.locations,l=>l!=null&&l.service==DigitalKingdomService.DungeonGuide);if(guide!=null){travel.dialogue=guide.dialogue;travel.npcName=guide.npcName;}travel.description="Selecciona un dungeon y despues uno de sus nodos desbloqueados.";city.locations=Array.FindAll(city.locations,l=>l!=null&&l.service!=DigitalKingdomService.DungeonGuide);
 var story=city.story;foreach(var notice in story.notices)if(notice.locationId=="city.dungeons")notice.locationId=travel.id;foreach(var notice in story.notices)foreach(var line in notice.dialogue){line.text=line.text.Replace("Habla con el guía de dungeons.","Habla con el guía de Fast Travel Station.").Replace("elige el reino.","elige el reino en Fast Travel Station.");}
 var groups=new List<CityDungeonDestination>(story.destinations);if(!groups.Exists(g=>g.map==DungeonMapSettings.Current))groups.Insert(0,new CityDungeonDestination{id="dungeon.original",displayName="Dungeon original",scenePath=city.fallbackDungeonScene,map=DungeonMapSettings.Current,requiredFlag="",allowEntryWithoutNode=false,includeLegacyNodes=true});foreach(var route in groups)if(route.map!=DungeonMapSettings.Current){route.allowEntryWithoutNode=true;if(string.IsNullOrEmpty(route.entryNodeName)||route.entryNodeName=="Entrada")route.entryNodeName="Entrada del reino";}story.destinations=groups.ToArray();
 var map=Resources.Load<DungeonMapSettings>("RetroDungeonExperiment/Map");if(!map.entities.objects.Exists(e=>e.id=="retro.return.city"))map.entities.objects.Add(new DungeonMapEntity{id="retro.return.city",displayName="Regresar a Digital Kingdom",cell=map.startCell,heading=(map.startHeading+2)%4,kind=DungeonEntityKind.Door,returnToDigitalKingdom=true,digitalEffects=true,doorAccess=DigitalDoorAccess.Cyan});
 foreach(var item in new UnityEngine.Object[]{city,travel,story,map.entities})EditorUtility.SetDirty(item);AssetDatabase.SaveAssets();return "Titulo editable, viajes agrupados y puerta de retorno listos";
 }
}
